const data = $input.first().json;
const summary = data.briefing_summary || 'Günlük pazarlama performansı brifingi başarıyla oluşturuldu.';
const anomalyCount = data.anomalies_count !== undefined ? data.anomalies_count : 0;
const topFindings = data.top_3_findings || [];
const generatedAt = new Date().toISOString();

const severityEmoji = { 'CRITICAL': '🔴', 'HIGH': '🟠', 'MEDIUM': '🟡', 'LOW': '🟢' };

const blocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "📊 Günlük Pazarlama Otomasyonu Yönetici Brifingi",
      "emoji": true
    }
  },
  {
    "type": "context",
    "elements": [
      {
        "type": "mrkdwn",
        "text": `*Zaman:* ${generatedAt} | *Durum:* Başarılı | *Toplam Anomali:* ${anomalyCount}`
      }
    ]
  },
  { "type": "divider" },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*Yönetici Özeti:*\n${summary}`
    }
  }
];

if (topFindings.length > 0) {
  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": "*🎯 Top 3 Kritik Operasyonel Bulgular:*"
    }
  });

  topFindings.forEach((f, idx) => {
    const emoji = severityEmoji[f.severity] || '⚪';
    const findingText = `${emoji} *Bulgu #${idx + 1}: ${f.campaign_name}*\n` +
      `📌 *Platform:* ${f.platform} | *Ülke:* ${f.country} | *Skor:* ${f.score}\n` +
      `📊 *Metrik Değişimi:* ${f.metric_change}\n` +
      `🔍 *Teşhis:* ${f.issue_type}\n` +
      `⚡ *Aksiyon:* ${f.operational_action}`;

    blocks.push({
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": findingText
      }
    });

    if (idx < topFindings.length - 1) {
      blocks.push({ "type": "divider" });
    }
  });
}

blocks.push({ "type": "divider" });

return [{ json: { blocks, summary, anomalies_count: anomalyCount, generated_at: generatedAt, top_3_findings: topFindings } }];

const inputJson = $input.first() ? $input.first().json : {};
const executionId = inputJson.execution_id || inputJson.executionId || $execution.id;
const failedStage = inputJson.failed_stage || inputJson.stage || 'Pipeline Execution';
const errorMessage = inputJson.error || inputJson.message || 'Unknown pipeline execution failure';
const timestamp = new Date().toISOString();

const blocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": "🚨 CRITICAL ALERT: Pipeline Execution Failed",
      "emoji": true
    }
  },
  {
    "type": "section",
    "fields": [
      {
        "type": "mrkdwn",
        "text": `*Execution ID:* ${executionId}`
      },
      {
        "type": "mrkdwn",
        "text": `*Channel:* #marketing-alerts-critical`
      },
      {
        "type": "mrkdwn",
        "text": `*Failed Stage:* ${failedStage}`
      },
      {
        "type": "mrkdwn",
        "text": `*Timestamp:* ${timestamp}`
      }
    ]
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*Error Details:*\n\`\`\`${errorMessage}\`\`\``
    }
  }
];

return [{ json: { channel: "#marketing-alerts-critical", blocks, execution_id: executionId, failed_stage: failedStage, error_message: errorMessage, timestamp } }];
